from pathlib import Path
from html import escape,unescape
import re,json,base64,zipfile
root=Path('study');course=json.loads(Path('course-inventory/course-structure.json').read_text())
head=(root/'coverage-report.html').read_text().split('<main>',1)[0].replace('<title>Coverage and missing materials</title>','<title>ISC English Study Book</title>')
chapters=[];links=[]
for m in course['modules']:
 n=m['number'];d=root/f'modules/{n:02d}';s=(d/'index.html').read_text().split('<main>',1)[1].rsplit('</main>',1)[0]
 def local(match):
  attr,url=match.groups()
  return match[0] if url.startswith(('http:','https:','mailto:','#','data:')) else f'{attr}="modules/{n:02d}/{url}"'
 s=re.sub(r'(src|href)="([^"]+)"',local,s);s=re.sub(r'id="section-(\d+)"',lambda a:f'id="m{n}-section-{a[1]}"',s);s=re.sub(r'href="#section-(\d+)"',lambda a:f'href="#m{n}-section-{a[1]}"',s)
 headings=re.findall(r'<h2 id="([^"]+)">(.*?)</h2>',s,re.S);toc=''.join(f'<li><a href="#{ident}">{title}</a></li>' for ident,title in headings)
 chapters.append(f'<article id="module-{n}" class="chapter"><p class="module-label">MODULE {n:02d}</p><nav aria-label="Module {n} contents"><strong>In this module</strong><ul>{toc}</ul></nav>{s}</article>')
 links.append(f'<li><a href="#module-{n}"><b>{n:02d}</b> {escape(m["module"])}</a><span>{len(m["lessons"])} lessons</span></li>')
closing=(root/'next-steps.html').read_text().split('<main>',1)[1].rsplit('</main>',1)[0];closing=re.sub(r'id="section-(\d+)"',lambda m:f'id="closing-{m[1]}"',closing)
report=(root/'coverage-report.html').read_text().split('<main>',1)[1].rsplit('</main>',1)[0];report=re.sub(r'id="section-(\d+)"',lambda m:f'id="coverage-{m[1]}"',report)
css='''<style>.intro{padding:28px;background:#edf4fa;border-left:5px solid #006ba6}.intro h1{margin-top:0}.summary-count{font-size:20px;font-weight:650;color:#102f4d}.contents{list-style:none;padding:0;columns:2;column-gap:25px}.contents li{break-inside:avoid;padding:10px 0;border-bottom:1px solid #d4e0e9;margin:0}.contents a{display:block;text-decoration:none}.contents span{font-size:12px;color:#53687b}.contents b{display:inline-block;width:30px}.chapter{margin-top:50px;padding-top:20px;border-top:4px solid #c626ac}.module-label{font-size:13px;font-weight:700;letter-spacing:.1em;color:#53687b}.chapter nav{padding:18px;background:#f5f8fb;border:1px solid #dce5eb;border-radius:6px}.chapter nav ul{columns:2}.chapter nav li{font-size:13px;line-height:1.5}.search-tools{position:sticky;top:0;z-index:10;background:#102f4d;color:white;padding:12px;display:flex;gap:8px;align-items:center;flex-wrap:wrap;border-radius:5px;margin:20px 0}.search-tools input{flex:1;min-width:180px;margin:0;width:auto;border:0;border-radius:3px}.search-tools button{font:inherit;border:1px solid #b5c6d5;padding:8px;cursor:pointer;border-radius:3px}.search-tools output{font-size:12px;min-width:85px}mark{background:#ffdf70;color:#172c40}mark.current{outline:3px solid #c626ac}h1,h2,h3,article{scroll-margin-top:95px}figure img{height:auto;max-height:600px}dialog{max-width:95vw;border:1px solid #a6b9c9;border-radius:7px}dialog::backdrop{background:#102f4dbb}dialog img{max-width:88vw;max-height:82vh}dialog button{font:inherit;padding:8px 16px;float:right}details{border:1px solid #dce5eb;padding:18px;margin-top:40px}summary{cursor:pointer;font-weight:650}.appendix{margin-top:40px}@media(max-width:650px){main{padding:18px}.contents,.chapter nav ul{columns:1}.intro{padding:18px}.search-tools{position:static}h1,h2,h3,article{scroll-margin-top:15px}}@media print{.search-tools,.chapter nav,details,dialog{display:none}.chapter{break-before:page}.contents{columns:2}.intro{background:white}mark{background:transparent}.appendix{break-before:page}}</style>'''
search='''<div class="search-tools" role="search"><label for="book-search">Search notes</label><input id="book-search" type="search" placeholder="e.g. manager correlation" autocomplete="off"><button id="previous-match" type="button" aria-label="Previous match">↑</button><button id="next-match" type="button" aria-label="Next match">↓</button><output id="match-count" aria-live="polite">Enter a term</output></div>'''
intro='<section class="intro"><h1>Set Up and Administer<br>Identity Security Cloud</h1><p class="summary-count">English Study Book · 13 modules · 70 lessons · 501 retained image files</p><p>26,237 words of study notes follow the verified course order. Text is paraphrased; saved images retain their original English. Inspected tabs, accordions and process panels are expanded into readable sections.</p><p><strong>Image and media gaps remain.</strong> Some background artwork, separate narration and external resources are not included. See the <a href="#coverage">coverage and missing-materials section</a> for exact known gaps and unverified inventories.</p><p>Use the search below, or your browser’s Find command. Select an image for a larger view. The ZIP version keeps the same notes and images together for offline reading.</p><h2>Course contents</h2><ol class="contents">'+''.join(links)+'</ol><p><a href="#next-steps">Next Steps resources</a> · <a href="#coverage">Missing materials</a> · <a href="lesson-coverage.csv">Per-lesson coverage CSV</a></p></section>'
dashboard=(root/'coverage-dashboard.html').read_text().split('<main>',1)[1].rsplit('</main>',1)[0];dashboard=re.sub(r'id="section-(\d+)"',lambda m:f'id="status-{m[1]}"',dashboard)
body=intro+search+''.join(chapters)+'<article class="appendix" id="next-steps">'+closing+'</article><article class="appendix" id="coverage">'+report+'</article><details><summary>All 70 lessons: individual coverage records</summary>'+dashboard+'</details>'
js='''<dialog id="image-preview" aria-label="Full-size course image"><button id="close-preview" type="button">Close</button><p></p><img alt=""></dialog><script>(()=>{const preview=document.getElementById('image-preview');document.querySelectorAll('figure a').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();const img=link.querySelector('img');preview.querySelector('img').src=img.src;preview.querySelector('img').alt=img.alt;preview.querySelector('p').textContent=img.alt;preview.showModal()}));document.getElementById('close-preview').onclick=()=>preview.close();let matches=[],position=-1,timer;const input=document.getElementById('book-search'),out=document.getElementById('match-count');function move(step){if(!matches.length)return;matches.forEach(m=>m.classList.remove('current'));position=(position+step+matches.length)%matches.length;matches[position].classList.add('current');matches[position].scrollIntoView({block:'center'});out.textContent=(position+1)+' / '+matches.length}function find(){document.querySelectorAll('mark.search-hit').forEach(m=>{const p=m.parentNode;m.replaceWith(document.createTextNode(m.textContent));p.normalize()});matches=[];position=-1;const term=input.value.trim().toLowerCase();if(!term){out.textContent='Enter a term';return}document.querySelectorAll('article.chapter').forEach(article=>{const walk=document.createTreeWalker(article,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('script,style,nav')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});const nodes=[];while(walk.nextNode())nodes.push(walk.currentNode);nodes.forEach(node=>{const raw=node.textContent,low=raw.toLowerCase();if(!low.includes(term))return;const frag=document.createDocumentFragment();let start=0,at;while((at=low.indexOf(term,start))!==-1){frag.append(document.createTextNode(raw.slice(start,at)));const mark=document.createElement('mark');mark.className='search-hit';mark.textContent=raw.slice(at,at+term.length);frag.append(mark);matches.push(mark);start=at+term.length}frag.append(document.createTextNode(raw.slice(start)));node.replaceWith(frag)})});out.textContent=matches.length+' matches';if(matches.length)move(1)}input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(find,180)});input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();clearTimeout(timer);if(!matches.length)find();else move(e.shiftKey?-1:1)}});document.getElementById('next-match').onclick=()=>move(1);document.getElementById('previous-match').onclick=()=>move(-1)})();</script>'''
reader=head+css+'<main>'+body+'</main>'+js+'</html>'
(root/'index.html').write_text(reader);(root/'study-content.html').write_text(reader)
images=re.findall(r'<img[^>]*src="([^"]+)"',reader);assert len(set(images))==501,len(set(images))
for src in images:assert(root/src).is_file(),src
ids=re.findall(r'id="([^"]+)"',reader);assert len(ids)==len(set(ids))
for frag in re.findall(r'href="#([^"]+)"',reader):assert frag in ids,frag
print(json.dumps({'modules':len(chapters),'lesson_rows':70,'image_placements':len(images),'unique_image_files':len(set(images)),'anchors':'passed'}))
